      figure: "<svg viewBox=\"0 0 320 340\" width=\"100%\" style=\"max-width:420px;height:auto\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"ah-2023cs27\" markerWidth=\"8\" markerHeight=\"8\" refX=\"7\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 Z\" fill=\"currentColor\"/></marker></defs><text x=\"165\" y=\"12\" font-size=\"10\" fill=\"currentColor\">ENTRY</text><line x1=\"180\" y1=\"16\" x2=\"180\" y2=\"32\" stroke=\"currentColor\" stroke-width=\"1.3\" marker-end=\"url(#ah-2023cs27)\"/><text x=\"140\" y=\"38\" font-size=\"9\" fill=\"currentColor\">B1</text><rect x=\"140\" y=\"40\" width=\"90\" height=\"52\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\"/><text x=\"148\" y=\"56\" font-size=\"9\" fill=\"currentColor\">i = m - 1</text><text x=\"148\" y=\"70\" font-size=\"9\" fill=\"currentColor\">j = n</text><text x=\"148\" y=\"84\" font-size=\"9\" fill=\"currentColor\">a = 10</text><line x1=\"180\" y1=\"92\" x2=\"180\" y2=\"108\" stroke=\"currentColor\" stroke-width=\"1.3\" marker-end=\"url(#ah-2023cs27)\"/><text x=\"140\" y=\"114\" font-size=\"9\" fill=\"currentColor\">B2</text><rect x=\"140\" y=\"116\" width=\"90\" height=\"38\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\"/><text x=\"148\" y=\"132\" font-size=\"9\" fill=\"currentColor\">i = i + 1</text><text x=\"148\" y=\"146\" font-size=\"9\" fill=\"currentColor\">j = j - 1</text><path d=\"M140,150 L90,190\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" marker-end=\"url(#ah-2023cs27)\"/><text x=\"55\" y=\"188\" font-size=\"9\" fill=\"currentColor\">B3</text><rect x=\"55\" y=\"192\" width=\"60\" height=\"28\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\"/><text x=\"62\" y=\"210\" font-size=\"9\" fill=\"currentColor\">a = 20</text><line x1=\"180\" y1=\"154\" x2=\"180\" y2=\"250\" stroke=\"currentColor\" stroke-width=\"1.3\" marker-end=\"url(#ah-2023cs27)\"/><path d=\"M115,214 L165,250\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" marker-end=\"url(#ah-2023cs27)\"/><text x=\"140\" y=\"246\" font-size=\"9\" fill=\"currentColor\">B4</text><rect x=\"140\" y=\"250\" width=\"90\" height=\"32\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\"/><text x=\"148\" y=\"270\" font-size=\"9\" fill=\"currentColor\">i = a + 1</text><path d=\"M230,255 Q290,180 230,110\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\" marker-end=\"url(#ah-2023cs27)\"/><line x1=\"180\" y1=\"282\" x2=\"180\" y2=\"300\" stroke=\"currentColor\" stroke-width=\"1.3\" marker-end=\"url(#ah-2023cs27)\"/><text x=\"165\" y=\"316\" font-size=\"10\" fill=\"currentColor\">EXIT</text></svg>",
